import React, { useEffect, useState, useMemo, lazy, Suspense } from 'react'; // Import lazy and Suspense
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import PageErrorBoundary from './components/common/PageErrorBoundary';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import { tajweedCssVars } from './utils/tajweedParser';
import { PrayerTimesProvider } from './contexts/PrayerTimesContext';
import { MosqueProvider } from './contexts/MosqueContext';
import { AthanSettingsProvider } from './contexts/AthanSettingsContext';
import { QuranSettingsProvider } from './contexts/QuranSettingsContext'; // Moved up
import FloatingControls from './components/FloatingControls';
import { SKY, skyPalette, pickMode } from './config/skyTheme';
import Layout from './components/layout/Layout'; // Moved up
import apiConfig from './config/apiConfig';
import analyticsService from './services/analyticsService';

// Lazy load Pages
const HomePage = lazy(() => import('./pages/HomePage'));
const PrayerTimesPage = lazy(() => import('./pages/PrayerTimesPage'));
const CalendarPage = lazy(() => import('./pages/CalendarPage'));
const MobileAppPage = lazy(() => import('./pages/MobileAppPage'));
const RamadanPage = lazy(() => import('./pages/RamadanPage'));
const ApiDocPage = lazy(() => import('./pages/ApiDocPage'));
const AlexaSkillPage = lazy(() => import('./pages/AlexaSkillPage'));
const NiyyahPage = lazy(() => import('./pages/NiyyahPage'));
const TasmiPage = lazy(() => import('./pages/TasmiPage'));
const TasmiRecordPage = lazy(() => import('./pages/TasmiRecordPage'));
const AiAgentsPage = lazy(() => import('./pages/AiAgentsPage'));
const FeatureRequestPage = lazy(() => import('./pages/FeatureRequestPage'));
const VolunteerPage = lazy(() => import('./pages/VolunteerPage'));
const MosqueDetailPage = lazy(() => import('./pages/MosqueDetailPage'));
const MasjidRequestPage = lazy(() => import('./pages/MasjidRequestPage'));
const MihrabPage = lazy(() => import('./pages/MihrabPage'));
const PrayerIntentPage = lazy(() => import('./pages/PrayerIntentPage'));
const FAQSupportPage = lazy(() => import('./pages/FAQSupportPage'));
const QiblaPage = lazy(() => import('./pages/QiblaPage'));
const QuranPage = lazy(() => import('./pages/QuranPage'));
const LifestyleCompass = lazy(() => import('./components/lifestyle-compass/LifestyleCompass'));

const LegacyPrivacyPolicyRedirect = () => {
    useEffect(() => {
        window.location.replace('/privacy-policy/');
    }, []);

    return <div>Redirecting to Privacy Policy...</div>;
};

const LegacyTermsRedirect = () => {
    useEffect(() => {
        window.location.replace('/terms/');
    }, []);

    return <div>Redirecting to Terms of Use...</div>;
};

// Create context for theme toggle
export const ThemeContext = React.createContext({ toggleColorMode: () => {}, mode: 'light' });
console.log('App.js loaded');
const SKY_TYPE = !!SKY;
const SKY_HEAD = SKY_TYPE ? { fontFamily: '"Marcellus", "Marcellus Fallback", Georgia, "Amiri", serif' } : {};

function App() {
    // Get saved theme preference or default to 'light'
    const [mode, setMode] = useState(() => {
        // On a sky page the page theme follows the sky (night skies: night) unless the visitor chose a mode; the OS preference never wins over the sky.
        return pickMode({ saved: localStorage.getItem('theme-mode'), systemDark: window.matchMedia?.('(prefers-color-scheme: dark)').matches });
    });

    // Toggle between light and dark mode
    const toggleColorMode = () => {
        setMode((prevMode) => {
            const newMode = prevMode === 'light' ? 'dark' : 'light';
            localStorage.setItem('theme-mode', newMode);
            return newMode;
        });
    };

    // Listen for system theme preference changes
    useEffect(() => {
        if (SKY) return undefined; // the sky decides the theme (pickMode); the OS preference is not consulted
        const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

        // Update theme when system preference changes
        const handleChange = (e) => {
            if (!localStorage.getItem('theme-mode')) {
                setMode(e.matches ? 'dark' : 'light');
            }
        };
        
        mediaQuery.addEventListener('change', handleChange);
        return () => mediaQuery.removeEventListener('change', handleChange);
    }, []);

    // Initialize analytics
    useEffect(() => {
        analyticsService.initAnalytics({
            // You can override any defaults here
            // enabled: process.env.NODE_ENV === 'production',
        });
    }, []);

    // Log API configuration on startup
    useEffect(() => {
        if (process.env.NODE_ENV === 'development') {
            console.log('API Configuration:', {
                baseUrl: apiConfig.baseUrl,
                environment: process.env.NODE_ENV
            });
        }
    }, []);
    
   

    // Create theme with Islamic colors
    const theme = useMemo(() => createTheme({
        palette: SKY_TYPE ? { mode, ...skyPalette(mode === 'dark') } : {
            mode,
            primary: {
                main: '#006400',  // Dark Green
                light: '#2e7d32',
                dark: '#004d00',
                contrastText: '#fff'
            },
            secondary: {
                main: '#d4af37',  // Gold
                light: '#e4c04d',
                dark: '#aa8c2c',
                contrastText: '#000'
            },
            background: {
                default: mode === 'light' ? '#f8f7f2' : '#121212',  // Light parchment or dark background
                paper: mode === 'light' ? '#fff' : '#1E1E1E'
            },
            text: {
                primary: mode === 'light' ? '#333333' : '#E0E0E0',
                secondary: mode === 'light' ? '#555555' : '#AAAAAA'
            }
        },
        typography: {
            // K06: on the pages the Worker dresses in the shared Living Sky chrome (<html data-sky>), the type is the
            // sky's: Inter for text, Marcellus for headings (self-hosted by the Worker; Amiri and the system fonts cover Arabic and Urdu).
            fontFamily: SKY_TYPE ? '"Inter", "Inter Fallback", system-ui, -apple-system, "Segoe UI", "Amiri", sans-serif' : '"Roboto", "Arial", sans-serif',
            h1: { fontWeight: SKY_TYPE ? 400 : 600, ...SKY_HEAD },
            h2: { fontWeight: SKY_TYPE ? 400 : 600, ...SKY_HEAD },
            h3: { fontWeight: SKY_TYPE ? 400 : 500, ...SKY_HEAD },
            h4: { fontWeight: SKY_TYPE ? 400 : 500, ...SKY_HEAD },
            h5: { fontWeight: 500 },
            h6: { fontWeight: 500 }
        },
        shape: {
            borderRadius: 8
        },
        components: {
            MuiCssBaseline: {
                styleOverrides: {
                  ':root': tajweedCssVars(mode === 'dark'),
                  body: {
                    scrollbarWidth: 'thin',
                    '&::-webkit-scrollbar': {
                      width: '8px',
                    },
                    '&::-webkit-scrollbar-track': {
                      background: mode === 'light' ? '#f1f1f1' : '#333',
                    },
                    '&::-webkit-scrollbar-thumb': {
                      background: mode === 'light' ? '#bdbdbd' : '#555',
                      borderRadius: '4px',
                    },
                  },
                },
            },
            MuiCard: {
                styleOverrides: {
                    root: {
                        boxShadow: '0 3px 10px rgba(0,0,0,0.08)',
                        transition: 'transform 0.2s',
                        '&:hover': {
                            transform: 'translateY(-3px)'
                        }
                    }
                }
            },
            MuiButton: {
                styleOverrides: {
                    root: {
                        borderRadius: '6px',
                        textTransform: 'none',
                        fontWeight: 500,
                        padding: '8px 16px'
                    },
                    ...(SKY_TYPE ? {} : { containedPrimary: {
                        background: 'linear-gradient(135deg, #006400, #004d00)',
                        '&:hover': {
                            background: 'linear-gradient(135deg, #004d00, #003b00)'
                        }
                    } })
                }
            }
        }
    }), [mode]);

    const themeContextValue = useMemo(
        () => ({
            toggleColorMode,
            mode,
        }),
        [mode]
    );

    return (
        <ThemeContext.Provider value={themeContextValue}>
            <ThemeProvider theme={theme}>
                <CssBaseline />
                <PrayerTimesProvider>
                    <MosqueProvider>
                        <Router>
                            <AthanSettingsProvider>
                                <QuranSettingsProvider>
                                    <Layout>
                                        {/* Wrap Routes with Suspense */}
                                        <PageErrorBoundary>
                                        <Suspense fallback={<div style={{ minHeight: '100vh' }} aria-busy="true" />}>
                                            <Routes>
                                                <Route path="/" element={<HomePage />} />
                                                <Route path="/classic" element={<HomePage />} />
                                                <Route path="/prayer-times" element={<PrayerTimesPage />} />
                                                <Route path="/classic/prayer-times" element={<PrayerTimesPage />} />
                                                <Route path="/calendar" element={<CalendarPage />} />
                                                <Route path="/classic/calendar" element={<CalendarPage />} />
                                                <Route path="/qibla" element={<QiblaPage />} />
                                                <Route path="/classic/qibla" element={<QiblaPage />} />
                                                <Route path="/mobile-app" element={<MobileAppPage />} />
                                                <Route path="/classic/mobile-app" element={<MobileAppPage />} />
                                                <Route path="/ramadan" element={<RamadanPage />} />
                                                <Route path="/classic/ramadan" element={<RamadanPage />} />
                                                <Route path="/quran" element={<QuranPage />} />
                                                <Route path="/classic/quran" element={<QuranPage />} />
                                                <Route path="/lifestyle-compass" element={<LifestyleCompass />} />
                                                <Route path="/classic/lifestyle-compass" element={<LifestyleCompass />} />
                                                <Route path="/api" element={<ApiDocPage />} />
                                                <Route path="/classic/api" element={<ApiDocPage />} />
                                                <Route path="/privacy-policy" element={<LegacyPrivacyPolicyRedirect />} />
                                                <Route path="/terms" element={<LegacyTermsRedirect />} />
                                                <Route path="/terms-of-service" element={<LegacyTermsRedirect />} />
                                                <Route path="/alexa-skill" element={<AlexaSkillPage />} />
                                                <Route path="/classic/alexa-skill" element={<AlexaSkillPage />} />
                                                <Route path="/niyyah" element={<NiyyahPage />} />
                                                <Route path="/classic/niyyah" element={<NiyyahPage />} />
                                                <Route path="/tasmi" element={<TasmiPage />} />
                                                <Route path="/classic/tasmi" element={<TasmiPage />} />
                                                <Route path="/tasmi/record" element={<TasmiRecordPage />} />
                                                <Route path="/classic/tasmi/record" element={<TasmiRecordPage />} />
                                                <Route path="/ai-agents" element={<AiAgentsPage />} />
                                                <Route path="/classic/ai-agents" element={<AiAgentsPage />} />
                                                <Route path="/feature-request" element={<FeatureRequestPage />} />
                                                <Route path="/classic/feature-request" element={<FeatureRequestPage />} />
                                                <Route path="/volunteer" element={<VolunteerPage />} />
                                                <Route path="/mosque/:id" element={<MosqueDetailPage />} />
                                                <Route path="/masjid-request" element={<MasjidRequestPage />} />
                                                <Route path="/classic/masjid-request" element={<MasjidRequestPage />} />
                                                <Route path="/mihrab" element={<MihrabPage />} />
                                                <Route path="/classic/mihrab" element={<MihrabPage />} />
                                                <Route path="/mihrab/setup" element={<MihrabPage />} />
                                                <Route path="/classic/mihrab/setup" element={<MihrabPage />} />
                                                <Route path="/prayer-intent" element={<PrayerIntentPage />} />
                                                <Route path="/classic/prayer-intent" element={<PrayerIntentPage />} />
                                                <Route path="/faq-support" element={<FAQSupportPage />} />
                                                <Route path="/classic/faq-support" element={<FAQSupportPage />} />
                                            </Routes>
                                        </Suspense>
                                        </PageErrorBoundary>
                                        <FloatingControls />
                                    </Layout>
                                </QuranSettingsProvider>
                            </AthanSettingsProvider>
                        </Router>
                    </MosqueProvider>
                </PrayerTimesProvider>
            </ThemeProvider>
        </ThemeContext.Provider>
    );
}

export default App;