// The Living Sky tokens for the React pages (K06). The source of truth is scripts/sky/tokens.mjs, which the app
// cannot import (Create React App only builds src/); worker/test/shell.test.js checks this copy equals it.
// SKY is the sky the Worker wrote into <html data-sky>, or null when the page has no shared chrome (the /classic/ pages, a dev server).
export const SKIES = {
  fajr: { night: true, stops: ['#0E1431', '#2A2C58', '#7A5A86', '#EBB09D'], ink: '#FBF4EA', soft: '#E6DDE0', accent: '#F6C2A8', on: '#151A3A' },
  dhuhr: { night: false, stops: ['#BFD9DF', '#E3ECE6', '#F7EFD9'], ink: '#13241B', soft: '#34443A', accent: '#0E5C40', on: '#F7F1E3' },
  asr: { night: false, stops: ['#E3C68C', '#EFD7A5', '#F8E7C2'], ink: '#2A1C0C', soft: '#43321A', accent: '#52320A', on: '#FAF0DC' },
  maghrib: { night: true, stops: ['#1E1433', '#5A2847', '#B9523E', '#F09A5A'], ink: '#FFF4E8', soft: '#F3E3DF', accent: '#FFC58F', on: '#2A1426' },
  isha: { night: true, stops: ['#030B08', '#08201A', '#0E2A1E'], ink: '#F7F1E3', soft: '#C9D0C6', accent: '#D9B46A', on: '#0B2219' },
};
export const PAGES = {
  day: { bg: '#F6F2E9', ink: '#15241C', soft: '#4F564E', card: '#FFFDF8', line: '#E4DCC8', gold: '#8A6420', accent: '#0E5C40', band: '#F2EEE2' },
  night: { bg: '#07150F', ink: '#F3ECDD', soft: '#A9B8AE', card: '#0D2219', line: '#1F3A2D', gold: '#D9B46A', accent: '#D9B46A', band: '#0A1D15' },
};
export const SKY_NAME = (() => {
  try { const s = typeof document !== 'undefined' && document.documentElement.getAttribute('data-sky'); return SKIES[s] ? s : null; } catch (e) { return null; }
})();
export const SKY = SKY_NAME ? { name: SKY_NAME, ...SKIES[SKY_NAME] } : null;
/** The upper sky, for a hero: text sits on it in `SKY.ink`. */
export const skyGradient = (s = SKY, angle = '180deg') => `linear-gradient(${angle},${s.stops[0]} 0%,${s.stops[1]} 100%)`; // top two stops only: text on them is above 9:1 in every sky
/** The MUI palette on the sky's page tokens: accent for actions, gold for emphasis, card and line for surfaces. */
export function skyPalette(dark) {
  const p = dark ? PAGES.night : PAGES.day;
  const on = dark ? '#0B2219' : '#F7F1E3';
  return {
    primary: { main: p.accent, light: p.accent, dark: p.accent, contrastText: on },
    secondary: { main: p.gold, light: p.gold, dark: p.gold, contrastText: on },
    background: { default: p.bg, paper: p.card },
    text: { primary: p.ink, secondary: p.soft },
    divider: p.line,
    sky: { gradient: skyGradient(), ink: SKY.ink, soft: SKY.soft, accent: SKY.accent, on: SKY.on, band: p.band },
  };
}

/**
 * The page's light or dark mode (K07b). A saved choice wins; on a sky page the sky decides (night skies: dark) and the
 * OS preference is never consulted, so a night page cannot flip to light because the phone is in light mode; with no sky
 * (the /classic/ pages, a dev server) the OS preference decides, as before.
 */
export function pickMode({ saved, sky = SKY, systemDark = false } = {}) {
  if (saved === 'light' || saved === 'dark') return saved;
  if (sky) return sky.night ? 'dark' : 'light';
  return systemDark ? 'dark' : 'light';
}
