import React from 'react';
import { Box } from '@mui/material';
import ThemeToggle from './ThemeToggle';
import LanguageSelector from './LanguageSelector';

// The theme and language buttons. From 600px up they float at the bottom corner (inline-end, safe-area aware).
// On phones a floating pair covered page buttons (the Alexa page's Dashboard button in Urdu, K07b), so there
// they sit in the page flow, at the end of the content above the footer, and never cover anything.
export default function FloatingControls() {
  return (
    <Box
      data-floating-controls
      sx={{
        display: { xs: 'flex', sm: 'contents' },
        justifyContent: 'flex-end',
        gap: 1.5,
        px: 2,
        py: 2.5,
      }}
    >
      <ThemeToggle />
      <LanguageSelector />
    </Box>
  );
}
